#!/usr/bin/env bash
# ZONO — apply all THREE dashboard rebuilds (My Day + Daily Center + Office) and push.
# Run from the zono-os repo root:  bash apply-dashboards.sh
set -euo pipefail
git am --abort 2>/dev/null || true
git fetch origin main
git checkout main
git merge --ff-only origin/main 2>/dev/null || echo "(note: applying onto current HEAD)"
echo "" | base64 -d > /tmp/all-three-dashboards.patch
git am -3 /tmp/all-three-dashboards.patch
git push origin main
echo "✅ All three dashboards applied and pushed."
